package com.nexus.access.backend.place;
import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface PlaceRepository extends JpaRepository<Place,UUID> { @Query(value="SELECT p.id, p.name, p.address, p.accessibility_score AS accessibilityScore, ST_Distance(p.location, ST_SetSRID(ST_MakePoint(:longitude,:latitude),4326)::geography) AS distanceMeters, ST_Y(p.location::geometry) AS latitude, ST_X(p.location::geometry) AS longitude FROM places p WHERE p.is_active = true AND ST_DWithin(p.location, ST_SetSRID(ST_MakePoint(:longitude,:latitude),4326)::geography, :radius) ORDER BY distanceMeters ASC",nativeQuery=true) List<NearbyPlaceProjection> findNearby(@Param("latitude") double latitude,@Param("longitude") double longitude,@Param("radius") double radius); interface NearbyPlaceProjection { UUID getId(); String getName(); String getAddress(); Integer getAccessibilityScore(); Double getDistanceMeters(); Double getLatitude(); Double getLongitude(); } }
